<template><section class="demo-controls dashboard-panel" aria-labelledby="demo-title"><header class="panel-heading"><div><p>Demo mode</p><h2 id="demo-title">Demo Controls</h2></div><span>{{ progress }}% Complete</span></header><p>This is a simulation. No real connections are made.</p><div class="demo-options"><button v-for="(preset,key) in presets" :key="key" type="button" :class="{active:current===key}" :aria-pressed="current===key" @click="$emit('select',key)"><span>{{ current===key?'✓':'○' }}</span><span><strong>{{ preset.label }}</strong><small>{{ descriptions[key] }}</small></span></button></div><button class="demo-reset" type="button" @click="$emit('reset')">↻ Reset Demo</button></section></template>
